import {performance} from 'node:perf_hooks';
import {writeFileSync} from 'node:fs';
import {loadOrders} from './src/orders.mjs';
const iterations=5000, samples=5;
const upstream=async()=>[];
for(let i=0;i<1000;i++) await loadOrders(upstream,{budgetMs:1000});
const results=[];
for(let sample=0;sample<samples;sample++){
  let start=performance.now();
  for(let i=0;i<iterations;i++) await upstream();
  const directMs=performance.now()-start;
  start=performance.now();
  for(let i=0;i<iterations;i++) await loadOrders(upstream,{budgetMs:1000});
  const wrappedMs=performance.now()-start;
  results.push({sample,directMs,wrappedMs,directPerCallMs:directMs/iterations,wrappedPerCallMs:wrappedMs/iterations});
}
writeFileSync(new URL('./benchmark.json',import.meta.url),JSON.stringify({schemaVersion:1,environment:{node:process.version,platform:process.platform,arch:process.arch},method:{iterations,samples,warmup:1000,budgetMs:1000,input:'Immediate async empty-array upstream; no real network, production load, or concurrent callers',measurement:'performance.now wall time; direct and wrapped loops measured sequentially'},results,limits:['Single local process and runtime','No production SLA or real upstream measurements','Not evidence about cancellation behavior or all bottlenecks']},null,2)+'\n');
